(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 5000));
  const g = window.__wgDebug;
  // click the 4th swatch (a dark finish) and rotate a little
  const sw = root.querySelectorAll('.wg__swatch')[3];
  sw.click();
  await new Promise(r => setTimeout(r, 900));
  g.camera.position.set(6, 2.4, 12);
  g.camera.lookAt(0, 0, 0);
  g.camera.updateMatrixWorld();
  g.renderer.render(g.scene, g.camera);
  const url = g.renderer.domElement.toDataURL('image/png');
  return {name: (root.querySelector('[data-wg-name]')||{}).textContent, img: url};
})()
